import java.util.Scanner;

public class Main {
    static final int MAXN = 510;
    static long[][] c = new long[MAXN][MAXN];
    static long[] f = new long[MAXN];
    static long[] g = new long[MAXN];
    static long[][] dp = new long[MAXN][MAXN];
    static long[][] ways = new long[MAXN][MAXN];
    static long[][] dp2 = new long[MAXN][MAXN];
    static long[][] ways2 = new long[MAXN][MAXN];
    static long[][] dp0 = new long[MAXN][MAXN];
    static long[][] ways0 = new long[MAXN][MAXN];

    static long p;

    static void combine(long[] x, long y) {
        for (int i = 0; i < x.length; i++) {
            x[i] = (x[i] + y) % p;
        }
    }

    static long choose(long x) {
        return (x * (x - 1) / 2) % p;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        p = sc.nextLong();

        for (int i = 0; i < MAXN; i++) {
            c[i][0] = 1;
        }
        for (int i = 1; i < MAXN; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % p;
            }
        }

        f[0] = 0;
        g[0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long valA = c[i - 1][j - 1] * f[j - 1] % p * g[i - j] % p * (i + 1) % p;
                long valB = c[i - 1][j - 1] * g[j - 1] % p * f[i - j] % p * (i + 1) % p;
                combine(f, (valA + valB + c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p * ((choose(j) + choose(i - j + 1)) % p)) % p);
                combine(g, c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p * (i + 1) % p);
            }
        }

        for (int i = 0; i < MAXN; i++) {
            for (int j = 0; j < MAXN; j++) {
                dp[i][j] = 0;
                ways[i][j] = 0;
                dp0[i][j] = 0;
                ways0[i][j] = 0;
                dp2[i][j] = 0;
                ways2[i][j] = 0;
            }
        }

        dp[0][0] = 0;
        ways[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                for (int k = 0; k <= Math.min(j, m); k++) {
                    if (k == 0) {
                        dp0[i][j] = dp[j][0];
                        ways0[i][j] = ways[j][0];
                    }
                    // Reset dp2 and ways2 for current iteration
                    for (int a = 0; a <= Math.min(j + 1, MAXN - 1); a++) {
                        for (int b = 0; b <= Math.min(k + 1, MAXN - 1); b++) {
                            dp2[a][b] = 0;
                            ways2[a][b] = 0;
                        }
                    }
                    // Update dp2 and ways2
                    for (int j2 = 0; j2 <= Math.min(i, m); j2++) {
                        for (int k2 = 0; k2 <= Math.min(j2, m); k2++) {
                            if (k2 == 0) {
                                dp0[i][j2] = dp[j2][0];
                                ways0[i][j2] = ways[j2][0];
                            }
                            long val = dp[j2][k2];
                            long way = ways[j2][k2];
                            int rem = m - (j2 - k2);
                            if (j + 1 <= MAXN - 1 && k + 1 <= MAXN - 1) {
                                long comb = c[rem][k + 1] % p;
                                long gVal = g[k + 1] % p;
                                long fVal = f[k + 1] % p;
                                long addVal = (dp0[i][j2] * comb % p * gVal % p + ways0[i][j2] * comb % p * fVal % p) % p;
                                combine(dp2[j + 1][k + 1], addVal);
                                long totalWays = (ways0[i][j2] * comb % p * gVal % p);
                                combine(ways2[j + 1][k + 1], totalWays);
                            }
                        }
                    }
                }
            }
            // Copy dp2 and ways2 into dp and ways
            for (int j = 0; j < MAXN; j++) {
                for (int k = 0; k < MAXN; k++) {
                    dp[j][k] = dp2[j][k];
                    ways[j][k] = ways2[j][k];
                }
            }
        }

        long total = 0;
        for (int i = 0; i <= m; i++) {
            total = (total + dp[m][i]) % p;
        }
        System.out.println(total);
        sc.close();
    }
}
